const A=window.AUDIT;const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=[['overview','◈','Обзор'],['mechanics','▤','Механики'],['spells','✧','Заклинания и свитки'],['items','◇','Предметы'],['units','▦','Боевые единицы'],['sources','⌑','Источники и границы']];const statuses={missing:'Не реализовано',partial:'Упрощено',implemented:'Есть обработчик',alias:'Нет привязки',excluded:'Вне объёма',review:'Требует проверки'};const priorities={high:'Значительное',medium:'Менее значительное',low:'Небольшое'};
let state={view:'overview',query:'',filter:'all',group:'all'};let returnFocus=null;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const nav=()=>{$('#nav').innerHTML=sections.map(([id,icon,label])=>`<button data-nav="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</button>`).join('');$('#breadcrumb').textContent=sections.find(s=>s[0]===state.view)[2]};
const heading=(eyebrow,title,text,stamp='')=>`<div class="page-heading"><div><span class="small-label">${eyebrow}</span><h1>${title}</h1><p>${text}</p></div>${stamp?`<span class="stamp">${stamp}</span>`:''}</div>`;
const card=(f,i)=>`<button class="finding" data-record="findings:${f.id}"><span class="index">${String(i+1).padStart(2,'0')}</span><div><div class="tag-row">${badge(priorities[f.priority],f.priority)}${f.quick?badge('Быстро поправить','quick'):''}<span class="small-label" style="letter-spacing:.2px">${esc(f.category)}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.summary)}</p></div><span class="arrow">↗</span></button>`;
function overview(){const high=A.findings.filter(f=>f.priority==='high'),quick=A.findings.filter(f=>f.quick);return heading('DISCIPLES II / BIG MAP','Атлас различий','Что меняет поведение агента, чего не хватает в магии и предметах и с чего начать исправления.','RISE OF THE ELVES')+`<div class="metrics"><div class="metric"><small>ЗНАЧИТЕЛЬНЫЕ РАЗЛИЧИЯ</small><div class="number">${high.length}</div><p>Влияют на стратегию обучения</p></div><div class="metric"><small>НЕТ ЭФФЕКТА ЗАКЛИНАНИЯ</small><div class="number">${A.stats.unimplementedSpells}<span>/ 120</span></div><p>У каждого есть и свиток</p></div><div class="metric"><small>БЫСТРЫЕ ИСПРАВЛЕНИЯ</small><div class="number">${quick.length}</div><p>Локальные изменения механик</p></div><div class="metric"><small>ПРЕДМЕТЫ В ЭТАЛОНЕ</small><div class="number">336</div><p>Включая 120 свитков</p></div></div><div class="overview-grid"><section><div class="section-heading"><h2>Сначала — влияние на игру</h2><button class="text-button" data-nav="mechanics">Все различия →</button></div><div class="finding-list">${high.slice(0,5).map(card).join('')}</div></section><div class="overview-aside"><section class="aside-panel"><h2>Магия: покрытие эффектов</h2>${['empire','mountain_clans','legions','undead_hordes','elves'].map((f,i)=>{const all=A.spells.filter(s=>s.factionKey===f&&s.status!=='excluded');const n=all.filter(s=>s.status!=='missing').length;const names=['Империя','Горные кланы','Легионы проклятых','Орды нежити','Альянс эльфов'];return `<div class="coverage-line"><div><span>${names[i]}</span><span>${all.length?n+'/'+all.length:'—'}</span></div><div class="bar"><span style="width:${all.length?n/all.length*100:0}%"></span><em style="flex:1"></em></div></div>`}).join('')}<div class="legend"><span>Обработчик есть</span><span>Не реализовано</span></div><p style="margin-top:16px;font-size:12px">Отложенные эффекты исключены. Область действия и точность параметров проверяются отдельно.</p></section><section class="aside-panel"><h2>Быстрое приближение к игре</h2>${quick.slice(0,3).map(f=>`<button class="quick-line" data-record="findings:${f.id}"><span>${esc(f.title)}</span><small>${esc(f.effort)}</small></button>`).join('')||'<p>Сверка локальных исправлений продолжается.</p>'}</section></div></div><div class="note">${A.phase==='research'?'Первый срез исследования. Каталоги и доказательства дополняются.':'Приоритет — правила, которые меняют решения агента. Оценки сроков предполагают знакомство с кодом и включают проверку; это ориентиры, не обещание.'}</div>`}
function toolbar(groups,options){return `<div class="toolbar"><input id="query" type="search" aria-label="Поиск по текущему разделу" placeholder="Найти название, эффект или ID…" value="${esc(state.query)}"><select id="filter" aria-label="Статус или приоритет">${options.map(([v,l])=>`<option value="${v}" ${state.filter===v?'selected':''}>${esc(l)}</option>`).join('')}</select>${groups.length?`<select id="group" aria-label="Категория"><option value="all">Все категории</option>${groups.map(x=>`<option ${state.group===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:''}<span id="result-count" class="result-count"></span></div><div id="results"></div>`}
function collection(){const v=state.view;const config={mechanics:['ПРИОРИТЕТЫ / 01','Механики','Подтверждённые различия, влияние на обучение и конкретный следующий шаг.'],spells:['КНИГА МАГИИ / 02','Заклинания и свитки','120 заклинаний сопоставлены с книгой магии среды и соответствующими свитками по ID игры.'],items:['ИНВЕНТАРЬ / 03','Предметы','Все 336 записей GItem.DBF. Свитки вынесены в книгу магии; сюжетные предметы исключены из различий.'],units:['БОЕВЫЕ ДАННЫЕ / 04','Боевые единицы','Проверка характеристик и развития. Дубликаты DBF, сюжетные варианты и разные локализации не считаются отсутствующими юнитами.']}[v];const data=v==='mechanics'?A.findings:A[v];const groups=[...new Set(data.map(r=>r.category||r.faction).filter(Boolean))];let opts=v==='mechanics'?[['all','Все приоритеты'],['high','Значительные'],['medium','Менее значительные'],['quick','Быстро поправить']]:[['all','В рамках аудита'],['gaps','Только различия'],['missing','Не реализовано'],['partial','Упрощено'],['alias','Нет привязки'],['implemented','Есть обработчик'],['review','Требует проверки']];return heading(...config)+(v==='spells'?`<div class="summary-strip"><span><strong>99</strong> обработчиков</span><span><strong>12</strong> отсутствующих эффектов в объёме</span><span><strong>9</strong> отложенных эффектов вне объёма</span></div>`:v==='units'?`<div class="note">В игре ${A.stats.unitRecords} записей юнитов, в среде ${A.stats.envUnits} шаблона. Разность этих чисел не является числом отсутствующих существ. Здесь показаны только подтверждённые сопоставления.</div>`:'')+toolbar(groups,opts)}
function results(){const v=state.view;let data=v==='mechanics'?A.findings:A[v];data=data.filter(r=>{if(v==='items'&&(r.type==='Свиток'||r.status==='excluded'))return false;if(v!=='mechanics'&&r.status==='excluded')return false;const f=state.filter;return (f==='all'||(f==='quick'?r.quick:f==='gaps'?['missing','partial','alias','review'].includes(r.status):v==='mechanics'?r.priority===f:r.status===f))&&(state.group==='all'||(r.category||r.faction)===state.group)&&JSON.stringify(r).toLocaleLowerCase('ru').includes(state.query.toLocaleLowerCase('ru'))});$('#result-count').textContent=`${data.length} ${v==='mechanics'?'различий':'записей'}`;$('#results').innerHTML=!data.length?'<div class="empty">По этим условиям ничего не найдено. Измени поиск или фильтр.</div>':v==='mechanics'?`<div class="mechanics-grid">${data.map(card).join('')}</div>`:`<div class="table-wrap"><table><thead><tr><th class="table-name">${v==='spells'?'Заклинание / свиток':v==='items'?'Предмет':'Юнит'}</th><th class="table-status">Статус</th><th class="table-note">Результат сверки</th><th class="table-level">${v==='spells'?'Уровень':'Группа'}</th></tr></thead><tbody>${data.map(r=>`<tr><td><button class="row-button" data-record="${v}:${r.id}">${esc(r.title)}</button><small>${esc(r.nameEn||r.id)}</small></td><td>${badge(statuses[r.status],r.status)}</td><td>${esc(r.note||r.summary)}${r.scrollName?`<small>${esc(r.scrollName)}</small>`:''}</td><td>${esc(r.level||r.category||r.type||'')}<small>${esc(r.faction||'')}</small></td></tr>`).join('')}</tbody></table></div>`}
function sources(){return heading('ДОКАЗАТЕЛЬСТВА / 05','Источники и границы','При расхождении справочников приоритет у данных установленной Rise of the Elves. Независимая проверка поведения в запущенной игре не проводилась.')+`<div class="method-grid"><section class="source-card"><h3>Как читать статусы</h3><p>«Есть обработчик» — найден исполняемый путь в коде. «Упрощено» — эффект работает с другим поведением. «Нет привязки» — механизм существует, но имя или ссылка из DBF не подключены. «Не реализовано» — обработчик не найден. Непроверенные предположения выделены отдельно.</p></section><section class="source-card"><h3>Что именно сравнивалось</h3><p>Текущие файлы Big_map, включая незакоммиченные изменения, и Steam-установка Disciples II Rise of the Elves. Справочники разных дополнений не смешивались в один эталон. Проверка каталога не доказывает полное совпадение всех боёв.</p></section></div>${A.sources.map(s=>`<section class="source-card"><h3>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</h3><p>${esc(s.note)}</p>${s.detail?`<p><code>${esc(s.detail)}</code></p>`:''}</section>`).join('')}<section class="source-card"><h3>Отложено по твоему списку</h3><p>Эти механики и зависящие от них заклинания и предметы не включены в число различий.</p><div class="scope-chips">${A.exclusions.map(x=>badge(x,'excluded')).join('')}</div>${A.excludedNames?`<p>${esc(A.excludedNames)}</p>`:''}</section>`}
function render(){nav();$('#main').innerHTML=state.view==='overview'?overview():state.view==='sources'?sources():collection();if(!['overview','sources'].includes(state.view))results()}
function showDetail(key){const [group,id]=key.split(':');const r=A[group]?.find(x=>x.id===id);if(!r)return;returnFocus=document.activeElement;$('#detail-body').innerHTML=`<div class="tag-row">${r.priority?badge(priorities[r.priority],r.priority):badge(statuses[r.status],r.status)}${r.category?badge(r.category):''}${r.quick?badge('Быстро поправить','quick'):''}</div><h2 class="detail-title">${esc(r.title)}</h2>${r.nameEn?`<p style="color:var(--muted)">${esc(r.nameEn)} · ${esc(r.id)}</p>`:''}<div class="compare"><div><span class="small-label">В DISCIPLES II</span><p>${esc(r.original||r.game||'См. запись исходной таблицы.')}</p></div><div><span class="small-label">В УЧЕБНОЙ СРЕДЕ</span><p>${esc(r.env||r.note)}</p></div></div>${r.impact?`<section class="detail-section"><h3>Почему это важно</h3><p>${esc(r.impact)}</p></section>`:''}${r.fix?`<section class="detail-section"><h3>Как приблизить к игре${r.effort?' · '+esc(r.effort):''}</h3><p>${esc(r.fix)}</p></section>`:''}${r.scrollName?`<section class="detail-section"><h3>Свиток</h3><p>${esc(r.scrollName)} · ${esc(r.scrollId)}<br>${esc(r.scrollNote||r.note)}</p></section>`:''}<section class="detail-section"><h3>Основания</h3>${(r.sources||[]).map(s=>`<div class="evidence"><strong>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.label)} ↗</a>`:esc(s.label)}</strong>${esc(s.detail||'')}${s.code?`<code>${esc(s.code)}</code>`:''}</div>`).join('')}</section>`;$('#detail').showModal()}
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){state={view:n.dataset.nav,query:'',filter:'all',group:'all'};history.replaceState(null,'','#'+state.view);render();window.scrollTo({top:0,behavior:'instant'});return}const r=e.target.closest('[data-record]');if(r)showDetail(r.dataset.record)});document.addEventListener('input',e=>{if(e.target.id==='query'){state.query=e.target.value;results()}});document.addEventListener('change',e=>{if(e.target.id==='filter'||e.target.id==='group'){state[e.target.id]=e.target.value;results()}});$('#close-detail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});$('#detail').addEventListener('close',()=>returnFocus?.focus());if(sections.some(s=>'#'+s[0]===location.hash))state.view=location.hash.slice(1);render();
